#!/usr/bin/env node
"use strict";

/**
 * MCP acceptance harness — Phase 0.3 OAuth lifecycle baseline.
 *
 * A standalone black-box harness that targets a configurable production-component
 * MCP endpoint and asserts the full OAuth + MCP lifecycle:
 *
 *   L1  DCR (RFC 7591) registration succeeds with the supported OpenCode
 *       loopback redirect shape (201, client_id present, no client_secret);
 *   L2  Authorization Code flow with state and S256 PKCE completes (code
 *       present, state round-trips);
 *   L3  Token exchange completes and yields a resource-bound access token
 *       (3-part JWT) without manual JWT construction;
 *   L4  With that token, `initialize` succeeds (200, protocolVersion,
 *       capabilities, serverInfo);
 *   L5  `notifications/initialized` is accepted (202);
 *   L6  `tools/list` returns the expected nine tools, each with a description
 *       and a complete input schema;
 *   L7  `tools/call calendar_list` succeeds (200, content block).
 *
 * Baseline expectation (Phase 0.3): against the current production component,
 * L1-L7 FAIL because the authorization service is not deployed (the advertised
 * issuer host falls through to the CommonCal SPA) and the MCP gateway does not
 * implement the MCP lifecycle (initialize returns HTTP 400 with JSON-RPC -32601).
 * The harness asserts the target contract and therefore exits non-zero against
 * the current production component. That failure is the intentional, asserted
 * exit condition for this phase: it documents the current broken state that
 * later phases must fix. The harness is a regression gate: it stays red until
 * the production component implements the full OAuth + MCP lifecycle.
 *
 * This harness does NOT launch or depend on the slice1-lab binaries, and it
 * does NOT treat the lab binary as a release artifact. It reuses the
 * slice1-lab fixture shapes (DCR request shape, standard access-token claim
 * contract, scope catalog) and the MCP/OAuth standards-compliance
 * expectations. It is a pure HTTP client: it starts no servers and leaves no
 * processes behind.
 *
 * Configuration (command-line flags, then environment variables, then defaults):
 *   --url / MCP_URL             MCP endpoint URL (default: https://mcal.hajnal.space/mcp)
 *   --issuer / MCP_OAUTH_ISSUER configured authorization-server issuer
 *                               (default: https://cal.hajnal.space)
 *   --redirect / MCP_REDIRECT   admitted loopback redirect URI
 *                               (default: http://127.0.0.1:8765/callback)
 *   --timeout-ms / MCP_TIMEOUT_MS              request timeout ms (default: 15000)
 *   --record-dir / MCP_RECORD_DIR              record directory (default: OS temp dir)
 *
 * Exit codes:
 *   0  all lifecycle assertions pass (PASS)
 *   1  one or more lifecycle assertions fail (FAIL) — the intentional Phase 0.3
 *      baseline exit condition against the current production component
 *   2  harness error (invalid configuration, network failure, unexpected error)
 */

const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const {
  SCOPE_CATALOG,
  isPlainObject,
  decodeJwtPayload,
  runOAuthFlow,
  mcpCall,
  mcpNotify,
  deterministicStringify,
} = require("./lib");

const HARNESS_NAME = "commoncal-mcp-acceptance";
const HARNESS_VERSION = "0.3.0";

const DEFAULTS = {
  url: "https://mcal.hajnal.space/mcp",
  issuer: "https://cal.hajnal.space",
  redirect: "http://127.0.0.1:8765/callback",
  timeoutMs: 15000,
};

// The nine MCP tools (mcp-server/src/tools/mod.rs list_tools()).
const NINE_TOOLS = [
  "availability_find",
  "calendar_list",
  "event_get",
  "event_search",
  "event_create",
  "event_update",
  "reminder_set",
  "event_delete_prepare",
  "event_delete_commit",
];

class HarnessError extends Error {}

function env(name, fallback) {
  const v = process.env[name];
  return v === undefined || v === "" ? fallback : v;
}

function parseArgs(argv) {
  const flags = {};
  const unknown = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--help" || arg === "-h") {
      flags.help = true;
      continue;
    }
    if (arg.startsWith("--")) {
      const eq = arg.indexOf("=");
      let name;
      let value;
      if (eq !== -1) {
        name = arg.slice(2, eq);
        value = arg.slice(eq + 1);
      } else {
        name = arg.slice(2);
        const next = argv[i + 1];
        if (next !== undefined && !next.startsWith("--")) {
          value = next;
          i++;
        } else {
          value = "true";
        }
      }
      flags[name] = value;
    } else {
      unknown.push(arg);
    }
  }
  flags._unknown = unknown;
  return flags;
}

function printHelp() {
  console.log(`Usage: node mcp-acceptance/oauth-lifecycle.js [options]

Options:
  --url <url>              MCP endpoint URL (default: ${DEFAULTS.url})
  --issuer <url>           configured authorization-server issuer (default: ${DEFAULTS.issuer})
  --redirect <url>         admitted loopback redirect URI (default: ${DEFAULTS.redirect})
  --timeout-ms <n>         request timeout in ms (default: ${DEFAULTS.timeoutMs})
  --record-dir <dir>       directory for the deterministic record (default: OS temp dir)
  -h, --help               show this help

Environment variables MCP_URL, MCP_OAUTH_ISSUER, MCP_REDIRECT, MCP_TIMEOUT_MS,
and MCP_RECORD_DIR are also honored; command-line flags take precedence.
`);
}

function describeError(err) {
  if (err === undefined || err === null) return "unknown error";
  if (typeof err === "string") return err;
  return err.message || String(err);
}

function resolve(flags, flagName, envName, fallback) {
  if (flags[flagName] !== undefined) return flags[flagName];
  return env(envName, fallback);
}

function loadConfig(flags) {
  const url = resolve(flags, "url", "MCP_URL", DEFAULTS.url);
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    throw new HarnessError(`MCP_URL is not a valid URL: ${url}`);
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new HarnessError(`MCP_URL must use http or https: ${url}`);
  }

  const issuer = resolve(flags, "issuer", "MCP_OAUTH_ISSUER", DEFAULTS.issuer);
  let issuerParsed;
  try {
    issuerParsed = new URL(issuer);
  } catch {
    throw new HarnessError(`MCP_OAUTH_ISSUER is not a valid URL: ${issuer}`);
  }
  if (issuerParsed.protocol !== "http:" && issuerParsed.protocol !== "https:") {
    throw new HarnessError(`MCP_OAUTH_ISSUER must use http or https: ${issuer}`);
  }

  const redirect = resolve(flags, "redirect", "MCP_REDIRECT", DEFAULTS.redirect);
  let redirectParsed;
  try {
    redirectParsed = new URL(redirect);
  } catch {
    throw new HarnessError(`MCP_REDIRECT is not a valid URL: ${redirect}`);
  }

  const timeoutRaw = resolve(flags, "timeout-ms", "MCP_TIMEOUT_MS", String(DEFAULTS.timeoutMs));
  const timeoutMs = Number(timeoutRaw);
  if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
    throw new HarnessError(`MCP_TIMEOUT_MS must be a positive number: ${timeoutRaw}`);
  }

  return {
    url,
    issuer,
    redirect,
    timeoutMs,
    recordDir: resolve(flags, "record-dir", "MCP_RECORD_DIR", os.tmpdir()),
  };
}

// ---------------------------------------------------------------------------
// Assertions
// ---------------------------------------------------------------------------

/**
 * L1: DCR registration succeeds with the supported OpenCode loopback redirect
 * shape (201, client_id present, no client_secret).
 */
function assertL1(dcrResp) {
  const violations = [];
  if (dcrResp.status !== 201) {
    violations.push(
      `L1: DCR registration returned HTTP ${dcrResp.status}; expected 201`
    );
    return violations;
  }
  if (dcrResp.bodyJsonParseError !== null) {
    violations.push(
      `L1: DCR response is not valid JSON: ${dcrResp.bodyJsonParseError}`
    );
    return violations;
  }
  if (!isPlainObject(dcrResp.bodyJson)) {
    violations.push("L1: DCR response is not a JSON object");
    return violations;
  }
  const body = dcrResp.bodyJson;
  if (typeof body.client_id !== "string" || body.client_id.length === 0) {
    violations.push("L1: DCR response has no client_id");
  }
  if (body.client_secret !== undefined) {
    violations.push(
      "L1: DCR response contains a client_secret; a public client must not have one"
    );
  }
  return violations;
}

/**
 * L2: Authorization Code flow with state and S256 PKCE completes (code
 * present, state round-trips).
 */
function assertL2(authResult) {
  const violations = [];
  if (!authResult) {
    violations.push(
      "L2: authorization flow was not attempted (DCR failed or issuer unreachable)"
    );
    return violations;
  }
  if (!authResult.code) {
    violations.push(
      "L2: authorization flow did not return a code"
    );
    return violations;
  }
  if (authResult.state === null) {
    violations.push(
      "L2: authorization flow did not round-trip the state parameter"
    );
  }
  return violations;
}

/**
 * L3: Token exchange completes and yields a resource-bound access token
 * (3-part JWT) without manual JWT construction.
 */
function assertL3(tokenResp) {
  const violations = [];
  if (!tokenResp) {
    violations.push(
      "L3: token exchange was not attempted (authorization flow failed)"
    );
    return violations;
  }
  if (tokenResp.status !== 200) {
    violations.push(
      `L3: token exchange returned HTTP ${tokenResp.status}; expected 200`
    );
    return violations;
  }
  if (tokenResp.bodyJsonParseError !== null) {
    violations.push(
      `L3: token exchange response is not valid JSON: ${tokenResp.bodyJsonParseError}`
    );
    return violations;
  }
  if (!isPlainObject(tokenResp.bodyJson)) {
    violations.push("L3: token exchange response is not a JSON object");
    return violations;
  }
  const body = tokenResp.bodyJson;
  if (typeof body.access_token !== "string" || body.access_token.length === 0) {
    violations.push("L3: token exchange response has no access_token");
    return violations;
  }
  const parts = body.access_token.split(".");
  if (parts.length !== 3) {
    violations.push(
      `L3: access_token is not a 3-part JWT (has ${parts.length} parts)`
    );
  }
  return violations;
}

/**
 * L4: With the access token, `initialize` succeeds (200, protocolVersion,
 * capabilities, serverInfo).
 */
function assertL4(resp) {
  const violations = [];
  if (resp.status !== 200) {
    violations.push(
      `L4: initialize returned HTTP ${resp.status}; expected 200`
    );
    return violations;
  }
  if (resp.bodyJsonParseError !== null) {
    violations.push(
      `L4: initialize response is not valid JSON: ${resp.bodyJsonParseError}`
    );
    return violations;
  }
  if (!isPlainObject(resp.bodyJson)) {
    violations.push("L4: initialize response is not a JSON object");
    return violations;
  }
  const body = resp.bodyJson;
  if (body.error !== undefined) {
    const e = body.error;
    violations.push(
      `L4: initialize returned JSON-RPC error ${e.code !== undefined ? e.code : "?"}: ${e.message || "(no message)"}`
    );
    return violations;
  }
  if (body.result === undefined) {
    violations.push("L4: initialize response has no 'result' member");
    return violations;
  }
  const result = body.result;
  if (!isPlainObject(result)) {
    violations.push("L4: initialize 'result' is not an object");
    return violations;
  }
  if (typeof result.protocolVersion !== "string") {
    violations.push("L4: result.protocolVersion is missing or not a string");
  }
  if (!isPlainObject(result.capabilities)) {
    violations.push("L4: result.capabilities is missing or not an object");
  }
  const serverInfo = result.serverInfo;
  if (!isPlainObject(serverInfo)) {
    violations.push("L4: result.serverInfo is missing or not an object");
  } else {
    if (typeof serverInfo.name !== "string") {
      violations.push("L4: result.serverInfo.name is missing or not a string");
    }
    if (typeof serverInfo.version !== "string") {
      violations.push("L4: result.serverInfo.version is missing or not a string");
    }
  }
  return violations;
}

/**
 * L5: `notifications/initialized` is accepted (202).
 */
function assertL5(resp) {
  const violations = [];
  if (resp.status !== 202) {
    violations.push(
      `L5: notifications/initialized returned HTTP ${resp.status}; expected 202`
    );
  }
  return violations;
}

/**
 * L6: `tools/list` returns the expected nine tools, each with a description
 * and a complete input schema.
 */
function assertL6(resp) {
  const violations = [];
  if (resp.status !== 200) {
    violations.push(
      `L6: tools/list returned HTTP ${resp.status}; expected 200`
    );
    return violations;
  }
  if (resp.bodyJsonParseError !== null) {
    violations.push(
      `L6: tools/list response is not valid JSON: ${resp.bodyJsonParseError}`
    );
    return violations;
  }
  if (!isPlainObject(resp.bodyJson)) {
    violations.push("L6: tools/list response is not a JSON object");
    return violations;
  }
  const body = resp.bodyJson;
  if (body.error !== undefined) {
    const e = body.error;
    violations.push(
      `L6: tools/list returned JSON-RPC error ${e.code !== undefined ? e.code : "?"}: ${e.message || "(no message)"}`
    );
    return violations;
  }
  if (body.result === undefined) {
    violations.push("L6: tools/list response has no 'result' member");
    return violations;
  }
  const result = body.result;
  if (!isPlainObject(result)) {
    violations.push("L6: tools/list 'result' is not an object");
    return violations;
  }
  const tools = result.tools;
  if (!Array.isArray(tools)) {
    violations.push("L6: tools/list result has no 'tools' array");
    return violations;
  }
  // Assert the expected nine tools are present.
  const toolNames = tools.map((t) => (isPlainObject(t) ? t.name : null));
  for (const expected of NINE_TOOLS) {
    if (!toolNames.includes(expected)) {
      violations.push(`L6: tools/list is missing the expected tool '${expected}'`);
    }
  }
  // Assert each tool has a description and a complete input schema.
  for (const tool of tools) {
    if (!isPlainObject(tool)) continue;
    const name = tool.name || "(unnamed)";
    if (typeof tool.description !== "string" || tool.description.length === 0) {
      violations.push(`L6: tool '${name}' has no description`);
    }
    if (!isPlainObject(tool.inputSchema)) {
      violations.push(`L6: tool '${name}' has no inputSchema`);
    } else {
      if (tool.inputSchema.type !== "object") {
        violations.push(`L6: tool '${name}' inputSchema.type is not 'object'`);
      }
      if (!isPlainObject(tool.inputSchema.properties)) {
        violations.push(`L6: tool '${name}' inputSchema has no 'properties' object`);
      }
    }
  }
  return violations;
}

/**
 * L7: `tools/call calendar_list` succeeds (200, content block).
 */
function assertL7(resp) {
  const violations = [];
  if (resp.status !== 200) {
    violations.push(
      `L7: tools/call calendar_list returned HTTP ${resp.status}; expected 200`
    );
    return violations;
  }
  if (resp.bodyJsonParseError !== null) {
    violations.push(
      `L7: tools/call response is not valid JSON: ${resp.bodyJsonParseError}`
    );
    return violations;
  }
  if (!isPlainObject(resp.bodyJson)) {
    violations.push("L7: tools/call response is not a JSON object");
    return violations;
  }
  const body = resp.bodyJson;
  if (body.error !== undefined) {
    const e = body.error;
    violations.push(
      `L7: tools/call calendar_list returned JSON-RPC error ${e.code !== undefined ? e.code : "?"}: ${e.message || "(no message)"}`
    );
    return violations;
  }
  if (body.result === undefined) {
    violations.push("L7: tools/call response has no 'result' member");
    return violations;
  }
  const result = body.result;
  if (!isPlainObject(result)) {
    violations.push("L7: tools/call 'result' is not an object");
    return violations;
  }
  if (!Array.isArray(result.content) || result.content.length === 0) {
    violations.push("L7: tools/call result has no non-empty 'content' array");
  }
  return violations;
}

// ---------------------------------------------------------------------------
// Record
// ---------------------------------------------------------------------------

function writeRecord(cfg, record) {
  fs.mkdirSync(cfg.recordDir, { recursive: true });
  const recordPath = path.join(cfg.recordDir, "mcp-acceptance-oauth-lifecycle.json");
  const envelope = {
    harness: HARNESS_NAME,
    harnessVersion: HARNESS_VERSION,
    phase: "0.3-oauth-lifecycle",
    target: cfg.url,
    issuer: cfg.issuer,
    redirect: cfg.redirect,
    recordedBy: "oauth-lifecycle-probe",
    record,
  };
  fs.writeFileSync(recordPath, deterministicStringify(envelope) + "\n", "utf8");
  return recordPath;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main() {
  const flags = parseArgs(process.argv.slice(2));

  if (flags.help) {
    printHelp();
    return 0;
  }

  if (flags._unknown.length > 0) {
    console.error(
      `[mcp-acceptance] CONFIG ERROR: unknown argument(s): ${flags._unknown.join(", ")}`
    );
    console.error("[mcp-acceptance] Run with --help for usage.");
    return 2;
  }

  let cfg;
  try {
    cfg = loadConfig(flags);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] CONFIG ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }

  console.log(`[mcp-acceptance] target: ${cfg.url}`);
  console.log(`[mcp-acceptance] issuer: ${cfg.issuer}`);
  console.log(`[mcp-acceptance] redirect: ${cfg.redirect}`);

  const record = {
    assertions: {},
  };

  // L1-L3: OAuth flow (DCR + Authorization Code + S256 PKCE + token exchange).
  let flow;
  try {
    flow = await runOAuthFlow(cfg, cfg.issuer, cfg.redirect);
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.oauthFlow = flow.record;

  const l1 = assertL1(flow.record.dcr);
  record.assertions.L1 = { pass: l1.length === 0, violations: l1 };

  const l2 = assertL2(flow.record.authorize);
  record.assertions.L2 = { pass: l2.length === 0, violations: l2 };

  const l3 = assertL3(flow.record.token);
  record.assertions.L3 = { pass: l3.length === 0, violations: l3 };

  // If the OAuth flow failed, we cannot proceed to the MCP lifecycle.
  if (!flow.accessToken) {
    const allViolations = [...l1, ...l2, ...l3];
    let recordPath = null;
    try {
      recordPath = writeRecord(cfg, record);
    } catch (err) {
      console.error(
        `[mcp-acceptance] WARNING: could not write record: ${describeError(err)}`
      );
    }
    for (const [id, list] of [["L1", l1], ["L2", l2], ["L3", l3]]) {
      if (list.length === 0) {
        console.log(`[mcp-acceptance] ${id}: PASS`);
      }
    }
    if (allViolations.length > 0) {
      console.log("");
      console.log("[mcp-acceptance] FAIL: OAuth flow did not complete");
      for (const v of allViolations) {
        console.log(`  - ${v}`);
      }
      if (recordPath) {
        console.log(`[mcp-acceptance] deterministic record: ${recordPath}`);
      }
      console.log("");
      console.log(
        "[mcp-acceptance] This failure is the intentional Phase 0.3 baseline exit"
      );
      console.log(
        "[mcp-acceptance] condition: the current production component does not"
      );
      console.log(
        "[mcp-acceptance] deploy the authorization service or implement the MCP"
      );
      console.log(
        "[mcp-acceptance] lifecycle."
      );
      return 1;
    }
    console.log("");
    console.log("[mcp-acceptance] PASS: OAuth flow completed");
    if (recordPath) {
      console.log(`[mcp-acceptance] deterministic record: ${recordPath}`);
    }
    return 0;
  }

  // L4-L7: Authenticated MCP lifecycle.
  let initializeResp;
  try {
    initializeResp = await mcpCall(
      cfg,
      cfg.url,
      "initialize",
      {
        protocolVersion: "2025-03-26",
        capabilities: {},
        clientInfo: { name: HARNESS_NAME, version: HARNESS_VERSION },
      },
      1,
      flow.accessToken
    );
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.initialize = initializeResp;
  const l4 = assertL4(initializeResp);
  record.assertions.L4 = { pass: l4.length === 0, violations: l4 };

  let initializedResp;
  try {
    initializedResp = await mcpNotify(
      cfg,
      cfg.url,
      "notifications/initialized",
      {},
      flow.accessToken
    );
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.initialized = initializedResp;
  const l5 = assertL5(initializedResp);
  record.assertions.L5 = { pass: l5.length === 0, violations: l5 };

  let toolsListResp;
  try {
    toolsListResp = await mcpCall(
      cfg,
      cfg.url,
      "tools/list",
      {},
      2,
      flow.accessToken
    );
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.toolsList = toolsListResp;
  const l6 = assertL6(toolsListResp);
  record.assertions.L6 = { pass: l6.length === 0, violations: l6 };

  let calendarListResp;
  try {
    calendarListResp = await mcpCall(
      cfg,
      cfg.url,
      "tools/call",
      { name: "calendar_list", arguments: {} },
      3,
      flow.accessToken
    );
  } catch (err) {
    if (err instanceof HarnessError) {
      console.error(`[mcp-acceptance] PROBE ERROR: ${err.message}`);
      return 2;
    }
    throw err;
  }
  record.calendarList = calendarListResp;
  const l7 = assertL7(calendarListResp);
  record.assertions.L7 = { pass: l7.length === 0, violations: l7 };

  let recordPath = null;
  try {
    recordPath = writeRecord(cfg, record);
  } catch (err) {
    console.error(
      `[mcp-acceptance] WARNING: could not write record: ${describeError(err)}`
    );
  }

  const allViolations = [...l1, ...l2, ...l3, ...l4, ...l5, ...l6, ...l7];
  for (const [id, list] of [
    ["L1", l1],
    ["L2", l2],
    ["L3", l3],
    ["L4", l4],
    ["L5", l5],
    ["L6", l6],
    ["L7", l7],
  ]) {
    if (list.length === 0) {
      console.log(`[mcp-acceptance] ${id}: PASS`);
    }
  }

  if (allViolations.length > 0) {
    console.log("");
    console.log("[mcp-acceptance] FAIL: OAuth + MCP lifecycle is NOT compliant");
    for (const v of allViolations) {
      console.log(`  - ${v}`);
    }
    if (recordPath) {
      console.log(`[mcp-acceptance] deterministic record: ${recordPath}`);
    }
    console.log("");
    console.log(
      "[mcp-acceptance] This failure is the intentional Phase 0.3 baseline exit"
    );
    console.log(
      "[mcp-acceptance] condition: the current production component does not"
    );
    console.log(
      "[mcp-acceptance] deploy the authorization service or implement the MCP"
    );
    console.log(
      "[mcp-acceptance] lifecycle."
    );
    return 1;
  }

  console.log("");
  console.log("[mcp-acceptance] PASS: OAuth + MCP lifecycle are compliant");
  if (recordPath) {
    console.log(`[mcp-acceptance] deterministic record: ${recordPath}`);
  }
  return 0;
}

main()
  .then((code) => {
    process.exitCode = code;
  })
  .catch((err) => {
    console.error(`[mcp-acceptance] UNEXPECTED ERROR: ${describeError(err)}`);
    if (err && err.stack) {
      console.error(err.stack);
    }
    process.exitCode = 2;
  });

"use strict";

/**
 * Shared helpers for the Phase 0.3 (oauth-lifecycle) and Phase 0.4
 * (security-isolation) acceptance harnesses.
 *
 * This module is a pure HTTP client. It does NOT launch or depend on the
 * slice1-lab binaries, and it does NOT treat the lab binary as a release
 * artifact. It reuses the slice1-lab fixture shapes:
 *   - the DCR request shape (slice1-lab/negative_tests.py fresh_dcr,
 *     slice1-lab/auth-server/src/server.mjs validateRegisteredMetadata);
 *   - the standard access-token claim contract (slice1-lab/src/jwt.rs
 *     AccessClaims: iss, numeric sub, aud, exp, iat, client_id, scope, jti,
 *     amr);
 *   - the scope catalog (slice1-lab/src/common.rs SCOPE_CATALOG);
 *   - the negative-token / fail-closed cases (slice1-lab/negative_tests.py
 *     cases 3-9, slice1-lab/PROOF.md P7).
 *
 * It owns its own production-facing configuration, lifecycle, reporting, and
 * cleanup: it is a pure HTTP client, starts no servers, and leaves no
 * processes behind.
 */

const crypto = require("node:crypto");

// ---------------------------------------------------------------------------
// Scope catalog (reused from slice1-lab/src/common.rs SCOPE_CATALOG)
// ---------------------------------------------------------------------------

const SCOPE_CATALOG = [
  "commoncal.calendar.metadata.read",
  "commoncal.availability.read",
  "commoncal.event.read.basic",
  "commoncal.event.read.details",
  "commoncal.event.create",
  "commoncal.event.update",
  "commoncal.event.delete",
  "commoncal.reminder.read",
  "commoncal.reminder.write",
];

// A scope deliberately outside the catalog (slice1-lab/src/common.rs EVIL_SCOPE).
const EVIL_SCOPE = "evil.unknown.scope";

// ---------------------------------------------------------------------------
// base64url helpers
// ---------------------------------------------------------------------------

function b64urlEncode(buf) {
  return Buffer.from(buf).toString("base64url");
}

function b64urlDecode(str) {
  return Buffer.from(str, "base64url");
}

function b64urlJson(obj) {
  return b64urlEncode(JSON.stringify(obj));
}

// ---------------------------------------------------------------------------
// PKCE S256
// ---------------------------------------------------------------------------

/**
 * Compute the S256 code challenge for a verifier (RFC 7636).
 */
function s256Challenge(verifier) {
  return b64urlEncode(crypto.createHash("sha256").update(verifier).digest());
}

/**
 * Generate a random PKCE code verifier (43-128 chars, RFC 7636).
 */
function generateVerifier() {
  return b64urlEncode(crypto.randomBytes(48));
}

// ---------------------------------------------------------------------------
// JWT helpers (decode only; no signature verification)
// ---------------------------------------------------------------------------

/**
 * Decode a JWT payload (no signature verification). Returns the claims object
 * or null.
 */
function decodeJwtPayload(jwt) {
  const parts = jwt.split(".");
  if (parts.length !== 3) return null;
  try {
    return JSON.parse(b64urlDecode(parts[1]).toString("utf8"));
  } catch {
    return null;
  }
}

/**
 * Decode a JWT header (no signature verification). Returns the header object
 * or null.
 */
function decodeJwtHeader(jwt) {
  const parts = jwt.split(".");
  if (parts.length !== 3) return null;
  try {
    return JSON.parse(b64urlDecode(parts[0]).toString("utf8"));
  } catch {
    return null;
  }
}

/**
 * Tamper a JWT's payload (re-encode with modified claims) without re-signing.
 * The signature becomes invalid, but the point is that validation fails closed.
 */
function tamperJwtPayload(jwt, claimOverrides) {
  const parts = jwt.split(".");
  if (parts.length !== 3) throw new Error("not a 3-part JWT");
  const claims = decodeJwtPayload(jwt);
  if (!claims) throw new Error("cannot decode payload");
  Object.assign(claims, claimOverrides);
  return `${parts[0]}.${b64urlJson(claims)}.${parts[2]}`;
}

/**
 * Tamper a JWT's signature (replace with a random signature of the same length).
 */
function tamperJwtSignature(jwt) {
  const parts = jwt.split(".");
  if (parts.length !== 3) throw new Error("not a 3-part JWT");
  const sigBytes = b64urlDecode(parts[2]);
  const randomSig = b64urlEncode(crypto.randomBytes(sigBytes.length));
  return `${parts[0]}.${parts[1]}.${randomSig}`;
}

// ---------------------------------------------------------------------------
// HTTP helpers
// ---------------------------------------------------------------------------

/**
 * Perform one HTTP request and capture the full response deterministically.
 */
async function httpProbe(cfg, method, url, body, headers = {}) {
  const reqHeaders = { ...headers };
  let bodyString = null;
  if (body !== null && body !== undefined) {
    bodyString = typeof body === "string" ? body : JSON.stringify(body);
    if (!reqHeaders["Content-Type"] && !reqHeaders["content-type"]) {
      reqHeaders["Content-Type"] = "application/json";
    }
  }
  if (method === "POST" && !reqHeaders.Accept && !reqHeaders.accept) {
    reqHeaders.Accept = "application/json, text/event-stream";
  }

  let status;
  let respHeaders;
  let rawBody;
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), cfg.timeoutMs);
    let res;
    try {
      res = await fetch(url, {
        method,
        headers: reqHeaders,
        body: bodyString,
        signal: controller.signal,
        redirect: "manual",
      });
    } finally {
      clearTimeout(timer);
    }
    status = res.status;
    respHeaders = normalizeHeaders(res.headers);
    rawBody = await res.text();
  } catch (err) {
    throw new Error(`network failure contacting ${url}: ${err.message}`);
  }

  let bodyJson = null;
  let bodyJsonParseError = null;
  try {
    bodyJson = JSON.parse(rawBody);
  } catch (err) {
    bodyJsonParseError = err.message;
  }

  return {
    status,
    headers: respHeaders,
    bodyRaw: rawBody,
    bodyJson,
    bodyJsonParseError,
  };
}

/**
 * Normalize response headers into a plain object, dropping volatile /
 * hop-by-hop headers so the recorded response is deterministic.
 */
function normalizeHeaders(headers) {
  const skip = new Set([
    "date",
    "x-request-id",
    "set-cookie",
    "transfer-encoding",
    "connection",
    "keep-alive",
  ]);
  const out = {};
  for (const [key, value] of headers.entries()) {
    const k = key.toLowerCase();
    if (skip.has(k)) continue;
    if (k in out) {
      out[k] = [].concat(out[k], value);
    } else {
      out[k] = value;
    }
  }
  return out;
}

function isPlainObject(v) {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

// ---------------------------------------------------------------------------
// OAuth flow (DCR + Authorization Code + S256 PKCE + token exchange)
// ---------------------------------------------------------------------------

/**
 * Register a client through DCR (RFC 7591) using the supported OpenCode
 * loopback redirect shape. Mirrors the lab's DCR policy
 * (slice1-lab/auth-server/src/server.mjs validateRegisteredMetadata).
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} issuer  The issuer base URL.
 * @param {string} redirect  The admitted loopback redirect URI.
 * @returns {Promise<{status: number, body: object}>}
 */
async function dcrRegister(cfg, issuer, redirect) {
  const body = {
    client_name: "commoncal-mcp-acceptance",
    redirect_uris: [redirect],
    grant_types: ["authorization_code", "refresh_token"],
    response_types: ["code"],
    token_endpoint_auth_method: "none",
    scope: SCOPE_CATALOG.join(" "),
  };
  const url = `${issuer.replace(/\/$/, "")}/register`;
  const resp = await httpProbe(cfg, "POST", url, body);
  return resp;
}

/**
 * Drive the Authorization Code flow with S256 PKCE. Returns the authorization
 * code and state from the redirect.
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} issuer  The issuer base URL.
 * @param {string} clientId  The DCR client id.
 * @param {string} redirect  The admitted loopback redirect URI.
 * @param {string} scope  The requested scope.
 * @param {string} verifier  The PKCE code verifier.
 * @returns {Promise<{code: string|null, state: string|null, resp: object}>}
 */
async function authorize(cfg, issuer, clientId, redirect, scope, verifier) {
  const challenge = s256Challenge(verifier);
  const state = crypto.randomBytes(16).toString("hex");
  const params = new URLSearchParams({
    response_type: "code",
    client_id: clientId,
    redirect_uri: redirect,
    scope,
    state,
    code_challenge: challenge,
    code_challenge_method: "S256",
  });
  const url = `${issuer.replace(/\/$/, "")}/authorize?${params.toString()}`;
  const resp = await httpProbe(cfg, "GET", url, null);

  // Extract the code and state from the redirect Location header.
  let code = null;
  let returnedState = null;
  const location = resp.headers["location"];
  if (location) {
    try {
      const locUrl = new URL(location);
      code = locUrl.searchParams.get("code");
      returnedState = locUrl.searchParams.get("state");
    } catch {
      // Location is not a valid URL; leave code/state null.
    }
  }
  return { code, state: returnedState, resp };
}

/**
 * Exchange an authorization code for a token (Authorization Code + S256 PKCE).
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} issuer  The issuer base URL.
 * @param {string} code  The authorization code.
 * @param {string} clientId  The DCR client id.
 * @param {string} redirect  The admitted loopback redirect URI.
 * @param {string} verifier  The PKCE code verifier.
 * @returns {Promise<{status: number, body: object}>}
 */
async function tokenExchange(cfg, issuer, code, clientId, redirect, verifier) {
  const params = new URLSearchParams({
    grant_type: "authorization_code",
    code,
    redirect_uri: redirect,
    client_id: clientId,
    code_verifier: verifier,
  });
  const url = `${issuer.replace(/\/$/, "")}/token`;
  const resp = await httpProbe(cfg, "POST", url, params.toString(), {
    "Content-Type": "application/x-www-form-urlencoded",
  });
  return resp;
}

/**
 * Run the full OAuth flow: DCR + Authorization Code + S256 PKCE + token
 * exchange. Returns the access token and the full flow record.
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} issuer  The issuer base URL.
 * @param {string} redirect  The admitted loopback redirect URI.
 * @returns {Promise<{accessToken: string|null, clientId: string|null, record: object}>}
 */
async function runOAuthFlow(cfg, issuer, redirect) {
  const record = {
    dcr: null,
    authorize: null,
    token: null,
  };

  // 1. DCR.
  const dcrResp = await dcrRegister(cfg, issuer, redirect);
  record.dcr = dcrResp;
  const clientId = dcrResp.bodyJson && dcrResp.bodyJson.client_id;
  if (!clientId) {
    return { accessToken: null, clientId: null, record };
  }

  // 2. Authorization Code + S256 PKCE.
  const verifier = generateVerifier();
  const scope = SCOPE_CATALOG.join(" ");
  const authResult = await authorize(cfg, issuer, clientId, redirect, scope, verifier);
  record.authorize = authResult;
  if (!authResult.code) {
    return { accessToken: null, clientId, record };
  }

  // 3. Token exchange.
  const tokenResp = await tokenExchange(cfg, issuer, authResult.code, clientId, redirect, verifier);
  record.token = tokenResp;
  const accessToken = tokenResp.bodyJson && tokenResp.bodyJson.access_token;

  return { accessToken, clientId, record };
}

// ---------------------------------------------------------------------------
// MCP calls
// ---------------------------------------------------------------------------

/**
 * Send a JSON-RPC request to the MCP endpoint.
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} mcpUrl  The MCP endpoint URL.
 * @param {string} method  The JSON-RPC method.
 * @param {object} params  The JSON-RPC params.
 * @param {number} id  The JSON-RPC id.
 * @param {string|null} accessToken  The Bearer access token (or null).
 * @returns {Promise<object>} The response record.
 */
async function mcpCall(cfg, mcpUrl, method, params, id, accessToken) {
  const body = {
    jsonrpc: "2.0",
    id,
    method,
    params,
  };
  const headers = {};
  if (accessToken) {
    headers.Authorization = `Bearer ${accessToken}`;
  }
  return httpProbe(cfg, "POST", mcpUrl, body, headers);
}

/**
 * Send a JSON-RPC notification to the MCP endpoint (no id expected).
 *
 * @param {object} cfg  Harness configuration.
 * @param {string} mcpUrl  The MCP endpoint URL.
 * @param {string} method  The JSON-RPC method.
 * @param {object} params  The JSON-RPC params.
 * @param {string|null} accessToken  The Bearer access token (or null).
 * @returns {Promise<object>} The response record.
 */
async function mcpNotify(cfg, mcpUrl, method, params, accessToken) {
  const body = {
    jsonrpc: "2.0",
    method,
    params,
  };
  const headers = {};
  if (accessToken) {
    headers.Authorization = `Bearer ${accessToken}`;
  }
  return httpProbe(cfg, "POST", mcpUrl, body, headers);
}

// ---------------------------------------------------------------------------
// Deterministic JSON
// ---------------------------------------------------------------------------

/**
 * Serialize a value to deterministic JSON (object keys sorted recursively).
 */
function deterministicStringify(value) {
  function sort(value) {
    if (Array.isArray(value)) return value.map(sort);
    if (isPlainObject(value)) {
      const out = {};
      for (const key of Object.keys(value).sort()) {
        out[key] = sort(value[key]);
      }
      return out;
    }
    return value;
  }
  return JSON.stringify(sort(value), null, 2);
}

module.exports = {
  SCOPE_CATALOG,
  EVIL_SCOPE,
  b64urlEncode,
  b64urlDecode,
  b64urlJson,
  s256Challenge,
  generateVerifier,
  decodeJwtPayload,
  decodeJwtHeader,
  tamperJwtPayload,
  tamperJwtSignature,
  httpProbe,
  normalizeHeaders,
  isPlainObject,
  dcrRegister,
  authorize,
  tokenExchange,
  runOAuthFlow,
  mcpCall,
  mcpNotify,
  deterministicStringify,
};

#!/usr/bin/env node
"use strict";

/**
 * Self-contained verification for the Phase 0.3 MCP oauth-lifecycle harness.
 *
 * This script proves oauth-lifecycle.js behaves correctly on BOTH paths:
 *
 *   1. FAIL path — against a server that exhibits the CURRENT production
 *      behavior (DCR returns SPA HTML, no OAuth flow), the harness must exit 1
 *      with focused violations on L1 (DCR), L2 (authorization), and L3
 *      (token exchange).
 *   2. PASS path — against a server that implements the full OAuth + MCP
 *      lifecycle, the harness must exit 0.
 *
 * It starts the verification-only mock server (mock/lifecycle-server.js) as a
 * child process, runs the harness (oauth-lifecycle.js) as a child process
 * against each endpoint, asserts the expected exit codes, and cleans up the
 * mock server.
 *
 * This is a test harness for the harness; it is not a release artifact and
 * does not touch production.
 *
 * Run:  node mcp-acceptance/verify-oauth-lifecycle.js
 * Exit: 0 if both paths behave as expected, 1 otherwise.
 */

const { spawn, execFile } = require("node:child_process");
const path = require("node:path");

const HERE = __dirname;
const MOCK = path.join(HERE, "mock", "lifecycle-server.js");
const HARNESS = path.join(HERE, "oauth-lifecycle.js");

function flagValue(argv, name, fallback) {
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === `--${name}`) return argv[i + 1];
    if (arg.startsWith(`--${name}=`)) return arg.slice(name.length + 3);
  }
  const envVal = process.env[name.toUpperCase()];
  return envVal !== undefined && envVal !== "" ? envVal : fallback;
}

const PORT = Number(flagValue(process.argv.slice(2), "port", process.env.MOCK_PORT || 4001));
const MCP_BASE = `http://127.0.0.1:${PORT}`;
const ISSUER_BASE = `http://127.0.0.1:${PORT + 1}`;

function log(msg) {
  console.log(`[verify-oauth-lifecycle] ${msg}`);
}

function runHarness(url, issuer, world) {
  return new Promise((resolve) => {
    execFile(
      process.execPath,
      [HARNESS, "--url", url, "--issuer", issuer, "--timeout-ms", "5000"],
      { timeout: 20000 },
      (error, stdout, stderr) => {
        const exitCode =
          error === null ? 0 : typeof error.code === "number" ? error.code : -1;
        resolve({ exitCode, stdout, stderr });
      }
    );
  });
}

async function waitForServer(url, timeoutMs = 10000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const res = await fetch(url);
      void res.status;
      await res.arrayBuffer();
      return true;
    } catch {
      await new Promise((r) => setTimeout(r, 100));
    }
  }
  return false;
}

function startMock(world) {
  return new Promise((resolve) => {
    const mock = spawn(process.execPath, [MOCK], {
      env: { ...process.env, MOCK_PORT: String(PORT), MOCK_WORLD: world },
      stdio: ["ignore", "pipe", "pipe"],
    });
    let mockOutput = "";
    mock.stdout.on("data", (d) => {
      mockOutput += d.toString();
    });
    mock.stderr.on("data", (d) => {
      mockOutput += d.toString();
    });
    resolve({ mock, getOutput: () => mockOutput });
  });
}

async function main() {
  let allPassed = true;
  const check = (label, ok) => {
    log(`  ${label} -> ${ok ? "OK" : "MISMATCH"}`);
    if (!ok) allPassed = false;
  };

  // 1. FAIL path: current-production behavior -> harness must exit 1.
  log("FAIL path: harness vs current-production behavior (expect exit 1)");
  const { mock: mockFail, getOutput: getFailOutput } = await startMock("current");
  const upFail = await waitForServer(`${MCP_BASE}/.well-known/oauth-protected-resource`);
  if (!upFail) {
    log("ERROR: mock server (current) did not become ready");
    log(getFailOutput());
    mockFail.kill("SIGTERM");
    return 1;
  }
  const fail = await runHarness(`${MCP_BASE}/mcp`, ISSUER_BASE, "current");
  check(`harness exit code: ${fail.exitCode} (expected 1)`, fail.exitCode === 1);
  check(
    "violation L1 (DCR) present",
    fail.stdout.includes("L1:")
  );
  mockFail.kill("SIGTERM");
  await new Promise((r) => setTimeout(r, 200));

  // 2. PASS path: compliant behavior -> harness must exit 0.
  log("PASS path: harness vs compliant lifecycle server (expect exit 0)");
  const { mock: mockPass, getOutput: getPassOutput } = await startMock("compliant");
  const upPass = await waitForServer(`${MCP_BASE}/.well-known/oauth-protected-resource`);
  if (!upPass) {
    log("ERROR: mock server (compliant) did not become ready");
    log(getPassOutput());
    mockPass.kill("SIGTERM");
    return 1;
  }
  const pass = await runHarness(`${MCP_BASE}/mcp`, ISSUER_BASE, "compliant");
  check(`harness exit code: ${pass.exitCode} (expected 0)`, pass.exitCode === 0);
  check("L1 passes", pass.stdout.includes("L1: PASS"));
  check("L2 passes", pass.stdout.includes("L2: PASS"));
  check("L3 passes", pass.stdout.includes("L3: PASS"));
  check("L4 passes", pass.stdout.includes("L4: PASS"));
  check("L5 passes", pass.stdout.includes("L5: PASS"));
  check("L6 passes", pass.stdout.includes("L6: PASS"));
  check("L7 passes", pass.stdout.includes("L7: PASS"));
  mockPass.kill("SIGTERM");
  await new Promise((r) => setTimeout(r, 200));

  log("");
  if (allPassed) {
    log("VERIFY PASS: oauth-lifecycle harness exits 1 on current-production behavior and 0 on compliant behavior.");
    return 0;
  }
  log("VERIFY FAIL: oauth-lifecycle harness behavior did not match expectations.");
  return 1;
}

main()
  .then((code) => {
    process.exitCode = code;
  })
  .catch((err) => {
    console.error(`[verify-oauth-lifecycle] UNEXPECTED ERROR: ${err && err.message ? err.message : String(err)}`);
    if (err && err.stack) console.error(err.stack);
    process.exitCode = 1;
  });

#!/usr/bin/env node
"use strict";

/**
 * Verification-only mock MCP + OAuth server for the Phase 0.3 (oauth-lifecycle)
 * and Phase 0.4 (security-isolation) acceptance harnesses.
 *
 * This is NOT a release artifact and NOT the production component. It exists
 * solely to exercise the harnesses' PASS and FAIL paths deterministically.
 *
 * The mock mirrors production's two-host topology and is driven by a single
 * world selector so its behavior is order-independent (a real OAuth client
 * discovers before it ever calls the MCP endpoint, so the world cannot be
 * inferred from the first MCP probe):
 *
 *   MOCK_WORLD=compliant (default) — the TARGET state:
 *     MCP host (MOCK_PORT, default 4001):
 *       GET  /.well-known/oauth-protected-resource
 *            -> RFC 9728 protected-resource metadata (valid JSON), naming the
 *               issuer host
 *       POST /mcp
 *            -> full authenticated MCP lifecycle (initialize,
 *               notifications/initialized, tools/list, tools/call
 *               calendar_list) gated by Bearer JWT validation + live grant
 *     Issuer host (MOCK_ISSUER_PORT, default MOCK_PORT + 1):
 *       GET  /.well-known/oauth-authorization-server
 *            -> RFC 8414 authorization-server metadata (valid JSON with
 *               authorization, token, registration, and JWKS endpoints)
 *       GET  /.well-known/openid-configuration
 *            -> CommonCal SPA HTML (mirrors the verified current state of
 *               cal.hajnal.space, which falls through to the SPA ingress)
 *       POST /register  -> DCR (RFC 7591) client registration
 *       GET  /authorize -> Authorization Code flow with S256 PKCE (auto-approves
 *                          login and consent, redirects back with the code)
 *       POST /token     -> Token exchange (Authorization Code + S256 PKCE)
 *       GET  /jwks      -> JWKS document (public key only)
 *
 *   MOCK_WORLD=current — the CURRENT production state:
 *     MCP host:
 *       GET  /.well-known/oauth-protected-resource
 *            -> valid JSON (production serves this document correctly)
 *       POST /mcp
 *            -> the CURRENT production gateway: only tools/list and tools/call
 *               are recognized; initialize (and everything else) is HTTP 400
 *               with JSON-RPC -32601 and no WWW-Authenticate header
 *               (mcp-server/src/gateway.rs)
 *     Issuer host:
 *       every route -> CommonCal SPA HTML (the authorization service is not
 *          deployed; the advertised issuer host is handled by core's "/"
 *          ingress and falls through to the SPA — docs/MCP-PRODUCTION-FIX-PLAN.md)
 *
 * The world is fixed at startup (MOCK_WORLD), so discovery, DCR, authorization,
 * token exchange, and the MCP lifecycle all agree regardless of request order.
 *
 * Run:  node mcp-acceptance/mock/lifecycle-server.js
 * Env:  MOCK_PORT (default 4001), MOCK_ISSUER_PORT (default MOCK_PORT + 1),
 *       MOCK_WORLD (default "compliant"; "current" mirrors production today)
 */

const http = require("node:http");
const {
  MockOAuthProvider,
  SCOPE_CATALOG,
  decodeJwtPayload,
} = require("./oauth-provider");

const PORT = Number(process.env.MOCK_PORT || 4001);
const ISSUER_PORT = Number(process.env.MOCK_ISSUER_PORT || PORT + 1);
const MCP_BASE = `http://127.0.0.1:${PORT}`;
const ISSUER_BASE = `http://127.0.0.1:${ISSUER_PORT}`;
const RESOURCE_URL = `${MCP_BASE}/mcp`;
const LOOPBACK_REDIRECT = "http://127.0.0.1:8765/callback";
const WORLD = (process.env.MOCK_WORLD || "compliant").toLowerCase();
const COMPLIANT = WORLD !== "current";

const SPA_HTML =
  '<!doctype html><html><head><meta charset="utf-8"><title>CommonCal</title></head><body><div id="root"></div><script src="/static/js/main.js"></script></body></html>';

// The mock OAuth provider (DCR + Authorization Code + S256 PKCE + token
// exchange + JWKS + token validation + grants).
